<template>
  <div class="app-container customer-card-page">
    <div class="page-heading"><div><h2>客户服务卡</h2><p>本门店员工共同维护客户偏好、注意事项、人均预算和到店服务记录。</p></div><el-button v-if="customerWriteEnabled" v-hasPermi="['inv:customerCard:add']" type="primary" icon="el-icon-plus" size="mini" @click="openForm()">新建服务卡</el-button></div>
    <el-alert v-if="!customerWriteEnabled" title="客户服务卡当前为只读模式" description="历史资料和服务记录仍可查询；新建、编辑、追加服务和归档暂未开放。" type="warning" show-icon :closable="false" class="filter-card"/>
    <customer-ops-summary />
    <el-card shadow="never" class="filter-card"><el-form :model="query" inline size="small"><el-form-item><el-input v-model="query.keyword" prefix-icon="el-icon-search" placeholder="姓名 / 手机 / 编码 / 偏好 / 注意事项" clearable @keyup.enter.native="load"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="使用中" value="0"/><el-option label="已归档" value="1"/></el-select></el-form-item><el-form-item label="偏好标签"><el-input v-model="query.preferenceTag" placeholder="如：岩茶" clearable/></el-form-item><el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form></el-card>
    <div v-loading="loading" class="card-grid">
      <el-card v-for="card in rows" :key="card.customerId" shadow="hover" class="customer-card" :class="{'is-archived':card.status==='1'}">
        <div class="card-head"><div class="customer-avatar"><i :class="card.photoNodeId ? 'el-icon-picture-outline' : 'el-icon-user'"/></div><div class="customer-title"><strong>{{ card.customerName }}</strong><span>{{ card.contactPhone || '未留手机号' }}</span></div><el-tag :type="card.status==='0'?'success':'info'" size="mini">{{ card.status==='0'?'使用中':'已归档' }}</el-tag></div>
        <div class="tag-row"><el-tag v-for="tag in tags(card.preferenceTags)" :key="tag" size="mini" type="warning" effect="plain">{{ tag }}</el-tag><span v-if="!tags(card.preferenceTags).length" class="muted">暂无偏好标签</span></div>
        <dl><div><dt>喜欢的茶</dt><dd>{{ card.teaPreferences || '待补充' }}</dd></div><div><dt>服务偏好</dt><dd>{{ card.brewingServicePreferences || '待补充' }}</dd></div><div class="caution"><dt>注意事项</dt><dd>{{ card.cautions || '无特别说明' }}</dd></div><div><dt>人均预算</dt><dd>{{ budget(card) }}</dd></div><div><dt>最近到店</dt><dd>{{ date(card.lastVisitDate) }}</dd></div></dl>
        <div class="card-actions"><el-button type="text" @click="openDetail(card)">查看记录</el-button><el-button v-if="customerWriteEnabled&&card.status==='0'" v-hasPermi="['inv:customerCard:record:add']" type="text" @click="openRecord(card)">追加服务</el-button><el-button v-if="customerWriteEnabled&&card.status==='0'" v-hasPermi="['inv:customerCard:edit']" type="text" @click="openForm(card)">编辑</el-button><el-dropdown v-if="customerWriteEnabled&&card.status==='0'" v-hasPermi="['inv:customerCard:archive']" @command="archive(card)"><el-button type="text">更多<i class="el-icon-arrow-down el-icon--right"/></el-button><el-dropdown-menu slot="dropdown"><el-dropdown-item command="archive">归档客户</el-dropdown-item></el-dropdown-menu></el-dropdown></div>
      </el-card>
      <el-empty v-if="!loading&&!rows.length" description="当前门店暂无客户服务卡"/>
    </div>
    <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load"/>

    <el-dialog :title="form.customerId?'编辑客户服务卡':'新建客户服务卡'" :visible.sync="formOpen" width="760px" append-to-body :close-on-click-modal="false">
      <el-form ref="cardForm" :model="form" :rules="rules" label-width="100px">
        <el-row :gutter="12"><el-col :span="12"><el-form-item label="客户姓名" prop="customerName"><el-input v-model="form.customerName" maxlength="128"/></el-form-item></el-col><el-col :span="12"><el-form-item label="联系电话"><el-input v-model="form.contactPhone" maxlength="32"/></el-form-item></el-col></el-row>
        <el-row :gutter="12"><el-col :span="12"><el-form-item label="客户编码"><el-input v-model="form.customerCode" maxlength="64"/></el-form-item></el-col><el-col :span="12"><el-form-item label="联系人"><el-input v-model="form.contactPerson" maxlength="64"/></el-form-item></el-col></el-row>
        <el-form-item v-if="driveEnabled" label="客户照片"><el-select v-model="form.photoNodeId" clearable filterable style="width:100%" placeholder="选择最近上传的云盘照片"><el-option v-for="file in recentImages" :key="file.nodeId" :label="file.nodeName||file.name" :value="file.nodeId"/></el-select><div class="tip">请先将照片上传到云盘，再绑定受控文件。</div></el-form-item>
        <el-form-item label="喜欢的茶"><el-input v-model="form.teaPreferences" type="textarea" :rows="2" maxlength="1000" placeholder="如：偏爱武夷岩茶、熟普，少喝绿茶"/></el-form-item>
        <el-form-item label="偏好标签"><el-input v-model="form.preferenceTags" maxlength="500" placeholder="使用英文逗号分隔，如：岩茶,熟普,老茶"/></el-form-item>
        <el-form-item label="服务偏好"><el-input v-model="form.brewingServicePreferences" type="textarea" :rows="2" maxlength="1000" placeholder="如：茶汤偏淡、使用盖碗、先闻香"/></el-form-item>
        <el-form-item label="注意事项"><el-input v-model="form.cautions" type="textarea" :rows="2" maxlength="1000" placeholder="忌口、过敏、称呼及其他服务注意事项"/></el-form-item>
        <el-row :gutter="12"><el-col :span="12"><el-form-item label="人均最低"><el-input-number v-model="form.budgetMin" :min="0" :precision="2" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="人均最高"><el-input-number v-model="form.budgetMax" :min="0" :precision="2" style="width:100%"/></el-form-item></el-col></el-row>
        <el-form-item label="最近到店"><el-date-picker v-model="form.lastVisitDate" type="date" value-format="yyyy-MM-dd" style="width:100%"/></el-form-item>
      </el-form><div slot="footer"><el-button @click="formOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></div>
    </el-dialog>

    <el-dialog title="追加服务记录" :visible.sync="recordOpen" width="620px" append-to-body><el-form :model="record" label-width="100px"><el-form-item label="服务日期"><el-date-picker v-model="record.serviceDate" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="到店人数"><el-input-number v-model="record.partySize" :min="1" style="width:100%"/></el-form-item><el-form-item label="本次茶饮"><el-input v-model="record.teaServed" maxlength="500"/></el-form-item><el-form-item label="偏好观察"><el-input v-model="record.preferenceSnapshot" type="textarea" :rows="2" maxlength="1000"/></el-form-item><el-form-item label="注意事项"><el-input v-model="record.cautionSnapshot" type="textarea" :rows="2" maxlength="1000"/></el-form-item><el-form-item label="服务备注"><el-input v-model="record.serviceNote" type="textarea" :rows="3" maxlength="1000"/></el-form-item><el-form-item label="消费金额"><el-input-number v-model="record.consumptionAmount" :min="0" :precision="2" style="width:100%"/></el-form-item></el-form><div slot="footer"><el-button @click="recordOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveRecord">追加记录</el-button></div></el-dialog>

    <el-drawer title="客户服务详情" :visible.sync="detailOpen" size="720px" append-to-body @closed="closeDetail"><div v-if="detail" class="detail-body"><div class="detail-head"><div><h3>{{ detail.customerName }}</h3><p>{{ detail.contactPhone || '-' }} · {{ budget(detail) }}</p></div><div class="detail-head-actions"><el-button v-hasPermi="['inv:customerCard:audit']" size="mini" :loading="auditLoading" @click="loadAudit(detail)">变更记录</el-button><el-button v-if="customerWriteEnabled && detail.status === '0'" v-hasPermi="['inv:customerCard:record:add']" type="primary" size="mini" @click="openRecord(detail)">追加服务</el-button></div></div><div v-if="detail.photoNodeId" v-loading="photoLoading" class="customer-photo"><img v-if="detailPhotoUrl" :src="detailPhotoUrl" :alt="detail.customerName + '客户照片'"/><el-button v-else type="text" @click="loadDetailPhoto(detail)">加载受控客户照片</el-button></div><el-descriptions :column="1" border size="small"><el-descriptions-item label="喜欢的茶">{{ detail.teaPreferences||'-' }}</el-descriptions-item><el-descriptions-item label="服务偏好">{{ detail.brewingServicePreferences||'-' }}</el-descriptions-item><el-descriptions-item label="注意事项">{{ detail.cautions||'-' }}</el-descriptions-item><el-descriptions-item label="创建人">{{ detail.createBy||'-' }}</el-descriptions-item><el-descriptions-item label="最后修改人">{{ detail.updateBy||detail.createBy||'-' }}</el-descriptions-item><el-descriptions-item label="最后修改时间">{{ dateTime(detail.updateTime||detail.createTime) }}</el-descriptions-item></el-descriptions><customer-service-history :customer-id="detail.customerId" :active="detailOpen" :refresh-token="detail.version"/><section v-if="auditVisible" class="audit-section"><h4>变更记录</h4><el-table v-loading="auditLoading" :data="auditRows" size="mini" border><el-table-column label="时间" prop="createTime" width="160"/><el-table-column label="动作" width="100"><template slot-scope="scope">{{ auditType(scope.row.changeType) }}</template></el-table-column><el-table-column label="操作人" prop="operatorName" width="110"/><el-table-column label="来源" width="80"><template slot-scope="scope">{{ auditSource(scope.row.sourceClient) }}</template></el-table-column><el-table-column label="变更范围" min-width="170"><template slot-scope="scope">{{ auditFields(scope.row.changedFields) }}</template></el-table-column><el-table-column label="脱敏摘要" min-width="210"><template slot-scope="scope">{{ auditSummary(scope.row.afterSummary||scope.row.beforeSummary) }}</template></el-table-column></el-table><el-empty v-if="!auditLoading&&!auditRows.length" description="暂无变更记录"/><p v-if="auditTotal>auditRows.length" class="audit-tip">仅显示最近 {{ auditRows.length }} 条，共 {{ auditTotal }} 条。</p></section></div></el-drawer>
  </div>
</template>

<style scoped lang="scss">
