  .card-grid > .el-empty {
    grid-column: 1 / -1;
    min-height: 240px;
    margin-top: 2px;
    padding: 30px;
    border: 1px solid #d8e3ea;
    border-radius: 14px;
    background: rgba(237, 244, 248, .58);
    box-sizing: border-box;
  }

  ::v-deep .card-grid > .el-empty .el-empty__image {
