  ::v-deep .el-alert__title {
    font-weight: 650;
  }

  ::v-deep .el-alert__description {
    color: var(--erp-text-secondary, #555b61);
  }
}
</style>

<script>
import { getSelectedDeptId } from '@/utils/shopContext'
const { createUiOperationScope } = require('@/utils/uiOperationScope')
import CustomerServiceHistory from "@/views/inventory/components/CustomerServiceHistory.vue"

import { listRecentDriveNodes } from '@/api/drive'
import { listCustomerServiceCards, getCustomerServiceCardCapabilities, listCustomerServiceAudits, getCustomerServiceCard, getCustomerServiceCardPhoto, createCustomerServiceCard, updateCustomerServiceCard, addCustomerServiceRecord, archiveCustomerServiceCard } from '@/api/inventory/customer'
import Vue from 'vue'
import CustomerOpsSummary from './components/CustomerOpsSummary'
Vue.component('CustomerOpsSummary', CustomerOpsSummary)
export default {name:'InvCustomerServiceCard',components:{CustomerServiceHistory},data(){return{loading:false,saving:false,writeEnabled:false,photoLoading:false,auditLoading:false,auditVisible:false,auditRows:[],auditTotal:0,detailPhotoUrl:'',detailRequestSeq:0,photoRequestSeq:0,auditRequestSeq:0,formRequestSeq:0,rows:[],total:0,formOpen:false,recordOpen:false,detailOpen:false,selected:null,detail:null,recentImages:[],query:{pageNum:1,pageSize:12,keyword:'',status:'0',preferenceTag:''},form:{},record:{},rules:{customerName:[{required:true,message:'客户姓名不能为空',trigger:'blur'}]}}},computed:{customerWriteEnabled(){return this.writeEnabled===true},driveEnabled(){return !!(this.$store&&this.$store.getters&&this.$store.getters.driveEnabled===true)}},watch:{recordOpen(value){if(!value){this.recordScope().invalidate('record');this.saving=false}},'$store.getters.id'(){this.resetRecordContext()},'$store.getters.token'(){this.resetRecordContext()}},created(){this._recordContextChanged=()=>this.resetRecordContext();window.addEventListener('erp:dept-changed',this._recordContextChanged);this.load();this.loadCapabilities()},beforeDestroy(){window.removeEventListener('erp:dept-changed',this._recordContextChanged);this.recordScope().deactivate();this.detailRequestSeq+=1;this.auditRequestSeq+=1;this.formRequestSeq+=1;this.clearDetailPhoto()},methods:{recordScope(){if(!this._recordScope)this._recordScope=createUiOperationScope(()=>({actorId:String(this.$store.getters.id||''),session:String(this.$store.getters.token||''),deptId:String(getSelectedDeptId()||'')}));return this._recordScope},resetRecordContext(){this.recordScope().invalidate();this.formRequestSeq+=1;this.formOpen=false;this.recordOpen=false;this.saving=false;this.selected=null;this.detailOpen=false;this.closeDetail();this.rows=[];this.total=0;this.load();this.loadCapabilities()},loadCapabilities(){return getCustomerServiceCardCapabilities().then(response=>{this.writeEnabled=!!(response&&response.data&&response.data.writeEnabled===true);if(this.writeEnabled&&this.driveEnabled)return this.loadRecent();this.recentImages=[]}).catch(()=>{this.writeEnabled=false;this.recentImages=[]})},requireWrite(){if(this.customerWriteEnabled)return true;this.$modal.msgWarning('客户服务卡当前为只读模式');return false},load(){const scope=this.recordScope(),operation=scope.begin('list');this.loading=true;return listCustomerServiceCards({...this.query}).then(r=>{if(!scope.isCurrent(operation))return;this.rows=r.rows||[];this.total=r.total||0}).finally(()=>{if(scope.isCurrent(operation))this.loading=false})},reset(){this.query={pageNum:1,pageSize:this.query.pageSize||12,keyword:'',status:'0',preferenceTag:''};this.load()},loadRecent(){if(!this.driveEnabled){this.recentImages=[];return Promise.resolve([])}return listRecentDriveNodes(50).then(r=>{if(!this.driveEnabled){this.recentImages=[];return[]}const a=r.rows||r.data||[];this.recentImages=Array.isArray(a)?a.filter(x=>x.nodeType!=='FOLDER'&&String(x.contentType||'').startsWith('image/')&&String(x.contentType||'')!=='image/svg+xml'):[];return this.recentImages}).catch(()=>{this.recentImages=[];return[]})},emptyForm(){return{customerId:undefined,customerName:'',customerCode:'',contactPerson:'',contactPhone:'',photoNodeId:undefined,teaPreferences:'',preferenceTags:'',brewingServicePreferences:'',cautions:'',budgetMin:undefined,budgetMax:undefined,lastVisitDate:undefined,version:undefined,requestKey:this.key('card'),sourceClient:'DESKTOP'}},openForm(card){if(!this.requireWrite())return;if(card&&card.status!=='0'){this.$modal.msgWarning('已归档客户只能查看，不能编辑');return}if(!card){this.form=this.emptyForm();this.formOpen=true;return}const customerId=card.customerId,requestSeq=++this.formRequestSeq;getCustomerServiceCard(customerId).then(r=>{if(requestSeq!==this.formRequestSeq)return;this.form={...this.emptyForm(),...r.data};this.form.requestKey=this.key('card');this.formOpen=true}).catch(error=>{if(requestSeq===this.formRequestSeq)this.$modal.msgError(this.errorMessage(error,'客户服务卡加载失败'))})},save(){if(!this.requireWrite()||this.saving)return;this.$refs.cardForm.validate(ok=>{if(!ok)return;this.saving=true;const data={...this.form};const p=this.form.customerId?updateCustomerServiceCard(this.form.customerId,data):createCustomerServiceCard(data);p.then(()=>{this.$modal.msgSuccess('客户服务卡已保存');this.formOpen=false;this.load()}).catch(error=>{this.$modal.msgError(this.errorMessage(error,'客户服务卡保存失败，请重试'))}).finally(()=>{this.saving=false})})},openDetail(card){const customerId=card&&card.customerId;if(!customerId)return;const scope=this.recordScope(),operation=scope.begin('detail'),requestSeq=++this.detailRequestSeq;this.clearDetailPhoto();this.auditRequestSeq+=1;this.auditVisible=false;this.auditRows=[];this.auditTotal=0;return getCustomerServiceCard(customerId).then(r=>{if(!scope.isCurrent(operation)||requestSeq!==this.detailRequestSeq||!r.data||String(r.data.customerId)!==String(customerId))return;this.detail=r.data;this.detailOpen=true;if(this.detail.photoNodeId)this.loadDetailPhoto(this.detail)}).catch(error=>{if(scope.isCurrent(operation)&&requestSeq===this.detailRequestSeq)this.$modal.msgError(this.errorMessage(error,'客户详情加载失败'))})},loadAudit(card){if(!card||!card.customerId)return;const customerId=card.customerId,requestSeq=++this.auditRequestSeq;this.auditVisible=true;this.auditLoading=true;return listCustomerServiceAudits({customerId,pageNum:1,pageSize:50}).then(r=>{if(requestSeq!==this.auditRequestSeq||!this.detail||Number(this.detail.customerId) !== Number(customerId))return;this.auditRows=r.rows||[];this.auditTotal=r.total||0}).catch(error=>{if(requestSeq===this.auditRequestSeq)this.$modal.msgError(this.errorMessage(error,'变更记录加载失败'))}).finally(()=>{if(requestSeq===this.auditRequestSeq)this.auditLoading=false})},loadDetailPhoto(card){if(!card||!card.customerId)return;const customerId=card.customerId,requestSeq=++this.photoRequestSeq;this.photoLoading=true;return getCustomerServiceCardPhoto(customerId,'preview').then(blob=>{if(requestSeq!==this.photoRequestSeq||!this.detail||Number(this.detail.customerId) !== Number(customerId))return;if(this.detailPhotoUrl)URL.revokeObjectURL(this.detailPhotoUrl);this.detailPhotoUrl=URL.createObjectURL(blob)}).catch(error=>{if(requestSeq===this.photoRequestSeq)this.$modal.msgError(this.errorMessage(error,'客户照片加载失败'))}).finally(()=>{if(requestSeq===this.photoRequestSeq)this.photoLoading=false})},clearDetailPhoto(){this.photoRequestSeq+=1;if(this.detailPhotoUrl)URL.revokeObjectURL(this.detailPhotoUrl);this.detailPhotoUrl='';this.photoLoading=false},closeDetail(){this.detailRequestSeq+=1;this.auditRequestSeq+=1;this.clearDetailPhoto();this.auditVisible=false;this.auditRows=[];this.auditTotal=0;this.detail=null},openRecord(card){if(!this.requireWrite())return;if(!card||card.status!=='0'){this.$modal.msgWarning('已归档客户不能追加服务记录');return}this.recordScope().invalidate('record');this.saving=false;this.selected=card;this.record={serviceDate:this.parseTime(new Date(),'{y}-{m}-{d} {h}:{i}:{s}'),partySize:1,teaServed:'',preferenceSnapshot:'',cautionSnapshot:'',serviceNote:'',consumptionAmount:undefined,requestKey:this.key('record'),sourceClient:'DESKTOP'};this.recordOpen=true},saveRecord(){if(!this.requireWrite()||this.saving||!this.recordOpen||!this.selected)return;const scope=this.recordScope(),customerId=String(this.selected.customerId),record=this.record,operation=scope.begin('record',customerId),detailId=String(this.detail&&this.detail.customerId||'');const current=()=>scope.isCurrent(operation,String(this.selected&&this.selected.customerId||''))&&this.record===record&&this.recordOpen;this.saving=true;return addCustomerServiceRecord(customerId,{...record}).then(r=>{if(!current())return;if(!r.data||String(r.data.customerId)!==customerId)throw Error('客户响应未确认，请刷新核对');this.saving=false;this.recordOpen=false;this.$modal.msgSuccess('服务记录已追加');if(this.detailOpen&&detailId===customerId&&String(this.detail&&this.detail.customerId||'')===customerId){this.detail=r.data;if(this.auditVisible)this.loadAudit(this.detail)}this.load()}).catch(error=>{if(current())this.$modal.msgError(this.errorMessage(error,'服务记录追加失败，请重试'))}).finally(()=>{if(current())this.saving=false})},archive(card){if(!this.requireWrite())return;if(card!=='archive'&&card&&card.customerId){this.selected=card}const row=this.selected;if(!row||row.status!=='0'){this.$modal.msgWarning('客户服务卡已归档');return}this.$prompt('请填写归档原因','归档客户',{inputValidator:v=>!!String(v||'').trim()||'原因不能为空'}).then(({value})=>archiveCustomerServiceCard(row.customerId,{version:row.version,reason:value,requestKey:`archive-${row.customerId}-${row.version}`,sourceClient:'DESKTOP'})).then(()=>{this.$modal.msgSuccess('客户已归档');this.load()}).catch(error=>{if(error!=='cancel'&&error!=='close')this.$modal.msgError(this.errorMessage(error,'客户归档失败，请重试'))})},auditType(v){return{CREATE:'新建',UPDATE:'编辑',ADD_RECORD:'追加服务',ARCHIVE:'归档'}[v]||(v?'其他操作':'-')},auditSource(v){return{MOBILE:'手机端',DESKTOP:'电脑端',WEB:'网页端',IMPORT:'导入'}[v]||(v?'其他来源':'-')},auditFields(v){const labels={ALL:'全部资料',NONE:'无字段变化',serviceRecord:'服务记录',status:'状态',customerName:'客户姓名',customerCode:'客户编码',contactPerson:'联系人',contactPhone:'联系电话',photoNodeId:'客户照片',teaPreferences:'茶饮偏好',preferenceTags:'偏好标签',brewingServicePreferences:'服务偏好',cautions:'注意事项',budgetMin:'最低预算',budgetMax:'最高预算',lastVisitDate:'最近到店'};return String(v||'').split(',').filter(Boolean).map(x=>labels[x]||'其他字段').join('、')||'-'},auditSummary(v){const labels={namePresent:'姓名',phonePresent:'手机号',preferencePresent:'偏好',cautionsPresent:'注意事项',budgetPresent:'预算',status:'状态',recordId:'记录'};return String(v||'').split(';').filter(Boolean).map(part=>{const i=part.indexOf('=');if(i<0)return'其他变更';const key=part.slice(0,i),value=part.slice(i+1);return(labels[key]||'其他内容')+'：'+(value==='Y'?'已填写':value==='N'?'未填写':value)}).join('；')||'-'},tags(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,6)},budget(c){if(c.budgetMin==null&&c.budgetMax==null)return'待补充';if(c.budgetMin!=null&&c.budgetMax!=null)return`¥${c.budgetMin} - ¥${c.budgetMax}/人`;return`约 ¥${c.budgetMin??c.budgetMax}/人`},date(v){return v?this.parseTime(v,'{y}-{m}-{d}'):'暂无记录'},dateTime(v){return v?this.parseTime(v,'{y}-{m}-{d} {h}:{i}'):'-'},errorMessage(error,fallback){return error&&error.message?error.message:fallback},key(prefix){return`${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,10)}`}}}
